import Foundation

// Distributed Cache Client with Security Headers Configuration
// Environment: Production web service with iframe embedding policies

struct CacheConfig {
    let redisHost: String
    let redisPort: Int
    let ttl: TimeInterval
    let securityHeaders: [String: String]
    let allowedOrigins: [String]
    let framePolicy: FramePolicy

    enum FramePolicy: String {
        case deny = "DENY"
        case sameOrigin = "SAMEORIGIN"
        case allowFrom = "ALLOW-FROM"
        case none = ""
    }
}

class SecurityHeaderProvider {
    private let config: CacheConfig
    private var headerCache: [String: String] = [:]
    private let cacheQueue = DispatchQueue(label: "com.cache.headers", attributes: .concurrent)

    init(config: CacheConfig) {
        self.config = config
        self.buildHeaderCache()
    }

    private func buildHeaderCache() {
        cacheQueue.async(flags: .barrier) { [weak self] in
            guard let self = self else { return }
            self.headerCache["X-Content-Type-Options"] = "nosniff"
            self.headerCache["X-XSS-Protection"] = "1; mode=block"
            self.headerCache["Strict-Transport-Security"] = "max-age=31536000; includeSubDomains"
            self.headerCache["X-Frame-Options"] = self.resolveFrameOptions()
            self.headerCache["Content-Security-Policy"] = self.resolveCSP()
        }
    }

    private func resolveFrameOptions() -> String {
        switch config.framePolicy {
        case .deny:
            return "DENY"
        case .sameOrigin:
            return "SAMEORIGIN"
        case .allowFrom:
            let origins = config.allowedOrigins.joined(separator: " ")
            return "ALLOW-FROM \(origins)"
        case .none:
            return "DENY"
        }
    }

    private func resolveCSP() -> String {
        let basePolicy = "default-src 'self'; script-src 'self'"
        let frameAncestors = resolveFrameAncestors()
        return "\(basePolicy); \(frameAncestors)"
    }

    private func resolveFrameAncestors() -> String {
        switch config.framePolicy {
        case .deny:
            return "frame-ancestors 'none'"
        case .sameOrigin:
            return "frame-ancestors 'self'"
        case .allowFrom:
            let origins = config.allowedOrigins.joined(separator: " ")
            return "frame-ancestors \(origins)"
        case .none:
            return "frame-ancestors 'none'"
        }
    }

    func getHeaders() -> [String: String] {
        var result: [String: String] = [:]
        cacheQueue.sync {
            result = self.headerCache
        }
        return result
    }
}

class DistributedCacheClient {
    private let config: CacheConfig
    private let headerProvider: SecurityHeaderProvider
    private var connectionPool: [String: Any] = [:]

    init(environment: String) {
        self.config = DistributedCacheClient.loadConfig(environment: environment)
        self.headerProvider = SecurityHeaderProvider(config: self.config)
    }

    static func loadConfig(environment: String) -> CacheConfig {
        let env = ProcessInfo.processInfo.environment

        let host = env["REDIS_HOST"] ?? "localhost"
        let port = Int(env["REDIS_PORT"] ?? "6379") ?? 6379
        let ttl = TimeInterval(env["CACHE_TTL"] ?? "3600") ?? 3600

        // Frame policy resolution chain:
        // 1. Check explicit FRAME_POLICY env var
        // 2. Fall back to environment-based defaults
        // 3. Apply origin allowlist from ALLOWED_ORIGINS
        let framePolicyRaw = env["FRAME_POLICY"] ?? defaultFramePolicy(for: environment)
        let framePolicy = CacheConfig.FramePolicy(rawValue: framePolicyRaw) ?? .deny

        let allowedOrigins = (env["ALLOWED_ORIGINS"] ?? "")
            .split(separator: ",")
            .map { String($0).trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }

        let securityHeaders = resolveBaseHeaders(environment: environment)

        return CacheConfig(
            redisHost: host,
            redisPort: port,
            ttl: ttl,
            securityHeaders: securityHeaders,
            allowedOrigins: allowedOrigins,
            framePolicy: framePolicy
        )
    }

    private static func defaultFramePolicy(for environment: String) -> String {
        // Environment-based frame policy defaults
        // Development: permissive for testing
        // Staging: same-origin for QA
        // Production: must be restrictive
        switch environment.lowercased() {
        case "development", "dev":
            return CacheConfig.FramePolicy.sameOrigin.rawValue
        case "staging", "stg":
            return CacheConfig.FramePolicy.sameOrigin.rawValue
        case "production", "prod":
            // Production always denies framing - partner integrations
            // must use API-based approaches, not iframe embedding
            return CacheConfig.FramePolicy.deny.rawValue
        default:
            return CacheConfig.FramePolicy.deny.rawValue
        }
    }

    private static func resolveBaseHeaders(environment: String) -> [String: String] {
        return [
            "X-Environment": environment,
            "X-Cache-Version": "2.1.0"
        ]
    }

    func responseHeaders() -> [String: String] {
        return headerProvider.getHeaders()
    }

    func get(key: String) -> Any? {
        // Simulated cache get
        return connectionPool[key]
    }

    func set(key: String, value: Any, ttl: TimeInterval? = nil) {
        connectionPool[key] = value
    }
}

// Application bootstrap
let environment = ProcessInfo.processInfo.environment["APP_ENV"] ?? "production"
let cacheClient = DistributedCacheClient(environment: environment)

// When serving responses, apply security headers
func handleRequest(path: String) -> (statusCode: Int, headers: [String: String], body: String) {
    let headers = cacheClient.responseHeaders()
    return (200, headers, "OK")
}
